    (
        4,
        12,
        '" XI,! ወሰበ ፡ ሰምፀ ፡ ሰናብላጥ ፡ ከመ ፡ ሐነጽነ ፡ አረፍተ ፡ ፈድፋደ ፣ ተምዕዐ ፡ ወኢኃ 2 ወዘ ፡ ወሰሐቁቆሙ ፡ ለአይሁድ። ወይቤ ፡ በቁቀድመ ፡ አኃዊሁ ፡ ወኃይለ ፡ ላምሮን ፡ ም ንት ፡ ወውእቱ ፡ „ይሎሙ ፡ ለአሉ ፡ አብዳን ፡ አይሁድ ፡ አለ ፡ የሐሕንጹ ፡ ሀገሮሙ = የ ሐድትጉኑ ፡ ሰሙ ፡ ወይሠውዐኑ ፡ ወይሠጽመሙ = ወይሦልዉጪተኑ ፡ አአበን ፡ ወአሙ-ንቱ።',
    ),
    (4, 13, "ወመጽአ ፡፣ ጦብያ ፡ አሞናዊ ፡ ኀቤሁ። ወተባበሀሉ ፡ አመኒ ፡ ሐነጹ ፡ አኮኑ ፡ | ፥ የዐርጉ ፡ ቈናጽል ፡ ወይነሥቱ ፡ አብነ ፡ አረፋቲሆሙ።"),
