        "ስማዕ ፡ አምላክነ ፡ ዘከመ ፡ ጽ ' ኣለት ፡ ኮነ ፡ ወሚጥ ፡ ሎሙ ፡ ጽእለቶሙ ፡ ላዕለ ፡ ርአሶስሙ ፡ ወአኅሥሮሙ ፡ በብሔ 2; ረ፡ተዩውዎቶሙ። ወኢትሠውር ፡ ሎሙ ፡ ኃጠ.አቶሙ ፡ አምቅድሜጫከ ፡ ወኢትዶም fs 31. ኣሓዙ።",
